    '<div class="dash-card"><b>' + (T.topTitleToday ? esc(dashTitleName(T.topTitleToday[0])) : '—') + '</b><span>Top title today</span><small>' + (T.topTitleToday ? T.topTitleToday[1] + ' view(s) today on this browser.' : 'No title views recorded yet today on this browser.') + '</small></div>' +
    '<div class="dash-card"><b>' + (T.topRefToday ? esc(T.topRefToday[0]) : '—') + '</b><span>Top referrer today</span><small>' + (T.topRefToday ? T.topRefToday[1] + ' visit(s) today via this referrer type.' : 'No visits recorded yet today on this browser.') + '</small></div>';
  const stEl = document.getElementById('dashStats');
